-- Reconcile schema drift: create every model the app references that no
-- earlier migration ever created.
--
-- The books / GST / payroll / banking / inventory surfaces (GstInvoice,
-- TdsEntry, PayrollRun, BankTransaction, BookAuditEntry, FixedAsset, EwayBill,
-- …) were added to prisma/schema.prisma without a matching migration, so a
-- freshly migrated database was missing 35 tables and every such request died
-- with P2021 ("no such table"). This migration is generated by
--   prisma migrate diff --from-config-datasource --to-schema prisma/schema.prisma
-- and is intentionally additive: it only creates missing objects plus two
-- schema-drift fixes Prisma detected (a redundant UserApiKey index and a
-- data-preserving CollaborativeUpdate rebuild). No data is deleted.

-- DropIndex
DROP INDEX "UserApiKey_keyPrefix_idx";

-- CreateTable
CREATE TABLE "GstInvoice" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "bookId" TEXT NOT NULL,
    "invoiceNumber" TEXT NOT NULL,
    "invoiceDate" TEXT NOT NULL,
    "invoiceType" TEXT NOT NULL,
    "supplyType" TEXT NOT NULL,
    "placeOfSupply" TEXT NOT NULL,
    "supplierGstin" TEXT,
    "supplierName" TEXT,
    "recipientGstin" TEXT,
    "recipientName" TEXT,
    "recipientState" TEXT,
    "taxableValue" INTEGER NOT NULL DEFAULT 0,
    "cgstAmount" INTEGER NOT NULL DEFAULT 0,
    "sgstAmount" INTEGER NOT NULL DEFAULT 0,
    "igstAmount" INTEGER NOT NULL DEFAULT 0,
    "cessAmount" INTEGER NOT NULL DEFAULT 0,
    "itcEligibility" TEXT NOT NULL DEFAULT 'eligible',
    "itcHeading" TEXT,
    "rcm" BOOLEAN NOT NULL DEFAULT false,
    "matched2a2b" BOOLEAN NOT NULL DEFAULT false,
    "matchedAt" DATETIME,
    "matchedById" TEXT,
    "gstr2aRef" TEXT,
    "mismatchReason" TEXT,
    "irn" TEXT,
    "irnDate" TEXT,
    "ackNumber" TEXT,
    "ackDate" TEXT,
    "source" TEXT NOT NULL DEFAULT 'manual',
    "status" TEXT NOT NULL DEFAULT 'draft',
    "period" TEXT NOT NULL,
    "reference" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    "createdById" TEXT,
    "updatedById" TEXT,
    CONSTRAINT "GstInvoice_bookId_fkey" FOREIGN KEY ("bookId") REFERENCES "Book" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);

